  [370637] = { "Evoca e congeda un destriero scheletrico. Il destriero obbedisce a chi lo evoca e si può usare come cavalcatura all'interno di Naxxramas. Qualsiasi azione ostile verso chi lo cavalca fa fuggire il destriero in preda alla paura.", { "Velocità a terra aumentata del $N1%. ", shape = { "1/0" } }, 0x67eeda0f, 0x2195529a, "uu" },
